import os,sys,subprocess,shutil,sqlite3,shlex
BIN='/workspace/executable'
def mknb(d, cfg=None, files=None, tmpl=None):
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d+'/.zk/templates', exist_ok=True)
    open(d+'/.zk/config.toml','w').write(cfg or '')
    open(d+'/.zk/templates/default.md','w').write('# {{title}}\n\n{{content}}\n')
    for k,v in (tmpl or {}).items(): open(d+'/.zk/templates/'+k,'w').write(v)
    for p,c in (files or {}).items():
        fp=os.path.join(d,p); os.makedirs(os.path.dirname(fp),exist_ok=True); open(fp,'w').write(c)
    con=sqlite3.connect(d+'/.zk/notebook.db')
    con.executescript(open('/tmp/zkh/schema.sql').read()); con.execute('PRAGMA user_version=8'); con.commit(); con.close()
    return d
def run(d,args,env=None,inp=b''):
    e=dict(os.environ); e.update(env or {})
    p=subprocess.run([BIN]+args, cwd=d, capture_output=True, env=e, input=inp)
    return p.returncode,p.stdout.decode('utf8','replace'),p.stderr.decode('utf8','replace')
def show(d,args,env=None,inp=b'',label=None):
    rc,o,er=run(d,args,env,inp)
    print('$ zk '+' '.join(shlex.quote(a) for a in args)+(' [env %s]'%env if env else ''))
    if o: print('OUT|'+o.replace('\n','\nOUT|')[:4000])
    else: print('OUT|<empty>')
    if er: print('ERR|'+er.replace('\n','\nERR|')[:4000])
    else: print('ERR|<empty>')
    print('RC=%d'%rc); print('-'*50)
    return rc,o,er
PYEOF
